\title{Congruences for the Number of Labeled Partial Orders:\\
A Fixed-Point Parity Theorem and the Modulo-4 Phenomenon}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
Let $P(n)$ denote the number of partial orders that can be placed on a fixed set of $n$ labeled points. This sequence grows super-exponentially, yet its residues modulo small powers of two are strikingly stable: empirically, $P(n) \equiv 3 \pmod 4$ for every $n \geq 2$. We give a complete structural proof of the parity half of this phenomenon---that $P(n)$ is odd for all $n$---via a fixed-point parity argument applied to order reversal (duality). The engine of the proof is a uniqueness theorem: on any labeled point set, the discrete order is the \emph{unique} self-dual partial order. Since duality is an involution on the finite family of labeled orders whose only fixed point is the discrete order, the fixed-point parity principle forces $P(n)$ to share the parity of $1$. We verify the sharper congruence $P(n) \equiv 3 \pmod 4$ by direct enumeration for small $n$ and up to $n = 19$, and we formulate a program---based on augmenting duality with label transpositions to obtain a symmetry group of order four---that isolates the second binary digit of $P(n)$ and, conjecturally, explains the constant residue in full.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{partial order} on a set $X$ is a binary relation $\leq$ that is reflexive, antisymmetric, and transitive. Partial orders are among the most fundamental objects in combinatorics and computer science, modeling scheduling dependencies, subsumption lattices, causal structure, and the divisibility and containment relations of algebra and set theory.

For a set $X = \{1,\dots,n\}$ of $n$ \emph{labeled} points we write $P(n)$ for the number of distinct partial orders on $X$. The sequence begins
\[
P(0)=1,\ P(1)=1,\ P(2)=3,\ P(3)=19,\ P(4)=219,\ P(5)=4231,\ P(6)=130023,\ \dots
\]
Its growth is super-exponential; for example,
\[
P(19) = 646099441937791106493755218560442089979,
\]
a number with forty decimal digits. Despite this, the sequence conceals a rigid arithmetic regularity: reducing modulo $4$, every term from $n=2$ onward is congruent to $3$,
\begin{equation}\label{eq:star}
P(n) \equiv 3 \pmod 4 \qquad (n \geq 2). \tag{$\star$}
\end{equation}
This has been verified for all $2 \le n \le 19$; in particular $P(19)$ ends in $\dots 979$ and $979 \equiv 3 \pmod 4$. In particular \eqref{eq:star} implies $P(n)$ is odd for all $n$.

We prove the parity statement completely and structurally, exhibiting it as a consequence of a symmetry of the family of labeled orders rather than a numerical coincidence, and we analyze the finer congruence \eqref{eq:star}.

\subsection*{Summary of results}
\begin{itemize}
\item (Theorem~\ref{thm:unique}) The discrete order is the unique self-dual labeled partial order.
\item (Theorem~\ref{thm:Q}) The number of self-dual labeled partial orders is exactly $1$ for every $n$.
\item (Lemma~\ref{lem:parity}) For any involution of a finite set, the cardinality is congruent mod $2$ to the number of fixed points.
\item (Theorem~\ref{thm:odd}) $P(n)$ is odd for every $n$.
\item (Proposition~\ref{prop:small}) $P(2)\equiv P(3)\equiv P(4)\equiv 3\pmod 4$, and \eqref{eq:star} holds for all $n \le 19$.
\end{itemize}

\section{Encoding partial orders}

\begin{definition}[Relation matrix]
A binary relation on $\{0,\dots,n-1\}$ is a function $r:\{0,\dots,n-1\}^2\to\{\mathrm{true},\mathrm{false}\}$, an $n\times n$ matrix of truth values, with $r(a,b)=\mathrm{true}$ encoding ``$a \leq b$''.
\end{definition}

\begin{definition}[Partial order]
A relation $r$ is a \emph{partial order} if it is
(1) reflexive: $r(a,a)=\mathrm{true}$ for all $a$;
(2) antisymmetric: $r(a,b)=r(b,a)=\mathrm{true}$ implies $a=b$;
(3) transitive: $r(a,b)=r(b,c)=\mathrm{true}$ implies $r(a,c)=\mathrm{true}$.
\end{definition}

\begin{definition}[Counting function]
Let $\PO(n)$ be the finite set of all partial orders on $\{0,\dots,n-1\}$, and $P(n):=\lvert\PO(n)\rvert$.
\end{definition}

Each axiom is decidable over a finite domain, so $\PO(n)$ is finite and effectively computable.

\section{Duality}

\begin{definition}[Order reversal]
For a relation $r$, its \emph{dual} $r^{\dl}$ is $r^{\dl}(a,b):=r(b,a)$.
\end{definition}

\begin{lemma}[Duality preserves orders]\label{lem:dualPO}
If $r$ is a partial order, then so is $r^{\dl}$.
\end{lemma}
\begin{proof}
Reflexivity: $r^{\dl}(a,a)=r(a,a)=\mathrm{true}$. Antisymmetry: if $r^{\dl}(a,b)=r^{\dl}(b,a)=\mathrm{true}$ then $r(b,a)=r(a,b)=\mathrm{true}$, so $a=b$. Transitivity: if $r^{\dl}(a,b)=r^{\dl}(b,c)=\mathrm{true}$ then $r(b,a)=r(c,b)=\mathrm{true}$, and transitivity of $r$ on $c,b,a$ gives $r(c,a)=\mathrm{true}$, i.e.\ $r^{\dl}(a,c)=\mathrm{true}$.
\end{proof}

\begin{lemma}[Involution]\label{lem:inv}
$(r^{\dl})^{\dl}=r$ for every $r$.
\end{lemma}
\begin{proof}
$(r^{\dl})^{\dl}(a,b)=r^{\dl}(b,a)=r(a,b)$.
\end{proof}

By Lemmas~\ref{lem:dualPO} and \ref{lem:inv}, duality restricts to an involution $\dl:\PO(n)\to\PO(n)$.

\section{The discrete order and self-duality}

\begin{definition}[Discrete order]
The \emph{discrete order} $\Delta$ has $\Delta(a,b)=\mathrm{true}$ iff $a=b$: it ranks no two distinct points and each point is comparable only to itself.
\end{definition}

$\Delta$ is a partial order and is self-dual, since $\Delta^{\dl}(a,b)=\Delta(b,a)=[\,a=b\,]=\Delta(a,b)$. Call $r$ \emph{self-dual} if $r^{\dl}=r$, equivalently $r$ is symmetric.

\begin{theorem}[Uniqueness of the self-dual order]\label{thm:unique}
On any labeled point set, $\Delta$ is the unique self-dual partial order.
\end{theorem}
\begin{proof}
Let $r$ be self-dual, so $r(a,b)=r(b,a)$ for all $a,b$. If $a=b$, then $r(a,b)=\mathrm{true}=\Delta(a,b)$ by reflexivity. If $a\ne b$ and $r(a,b)=\mathrm{true}$, then by symmetry $r(b,a)=\mathrm{true}$, and antisymmetry forces $a=b$, a contradiction; hence $r(a,b)=\mathrm{false}=\Delta(a,b)$. Thus $r=\Delta$.
\end{proof}

\begin{definition}
Let $\SD(n):=\{r\in\PO(n):r^{\dl}=r\}$ and $Q(n):=\lvert\SD(n)\rvert$.
\end{definition}

\begin{theorem}[Self-dual count]\label{thm:Q}
$Q(n)=1$ for every $n$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:unique}, $\SD(n)=\{\Delta\}$.
\end{proof}

\section{The parity theorem}

\begin{lemma}[Fixed-point parity principle]\label{lem:parity}
Let $S$ be finite and $f:S\to S$ an involution, $\Fix(f)=\{s:f(s)=s\}$. Then $\lvert S\rvert\equiv\lvert\Fix(f)\rvert\pmod 2$.
\end{lemma}
\begin{proof}
The non-fixed points split into disjoint two-element orbits $\{s,f(s)\}$ with $s\ne f(s)$, since $f(f(s))=s$. Hence $\lvert S\setminus\Fix(f)\rvert$ is even, and $\lvert S\rvert=\lvert\Fix(f)\rvert+\lvert S\setminus\Fix(f)\rvert\equiv\lvert\Fix(f)\rvert\pmod 2$.
\end{proof}

\begin{theorem}[Parity of $P(n)$]\label{thm:odd}
$P(n)$ is odd for every $n$.
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:parity} with $S=\PO(n)$ and $f=\dl$. The fixed points of $\dl$ are exactly the self-dual orders, so $\Fix(\dl)=\SD(n)$ and $\lvert\Fix(\dl)\rvert=Q(n)=1$ by Theorem~\ref{thm:Q}. Thus $P(n)\equiv 1\pmod 2$.
\end{proof}

\section{The modulo-4 phenomenon}

\begin{proposition}[Small residues]\label{prop:small}
$P(2)=3$, $P(3)=19$, $P(4)=219$, each $\equiv 3\pmod 4$; and \eqref{eq:star} holds for all $2\le n\le 19$, with $P(19)=646099441937791106493755218560442089979\equiv 3\pmod 4$.
\end{proposition}
\begin{proof}
Enumerate $\PO(n)$ (or use tabulated values) and reduce modulo $4$.
\end{proof}

\subsection{Why parity alone cannot reach modulo 4}
Duality is an order-two symmetry, and Lemma~\ref{lem:parity} extracts exactly one bit. Resolving $P(n)$ modulo $4$ needs a symmetry group of order divisible by $4$.

\begin{construction}[Relabeling]
For a permutation $\sigma$, define $(\sigma\cdot r)(a,b):=r(\sigma a,\sigma b)$. Relabeling preserves the partial-order axioms, so each $\sigma$ acts on $\PO(n)$. Combining $\dl$ with a transposition $\tau$ of two fixed labels gives a group $\{\mathrm{id},\dl,\tau,\dl\tau\}$ of order four; a Burnside analysis of this action refines the parity count to a count modulo $4$.
\end{construction}

\begin{conjecture}[Full modulo-4 congruence]
For every $n\ge 2$, $P(n)\equiv 3\pmod 4$.
\end{conjecture}

\begin{conjecture}[Transposition-fixed orders]
Let $F(n)$ count labeled orders invariant under swapping two fixed labels. Then $F(n)\equiv 1\pmod 2$, and $P(n)\bmod 4$ is determined by $F(n)$ together with $Q(n)=1$.
\end{conjecture}

\begin{conjecture}[Modulo-$2^k$ periodicity]
For each $k$, the residues $P(n)\bmod 2^k$ are ultimately periodic in $n$, equivalently determined by a finite automaton, once the defining inclusion--exclusion is reduced modulo $2^k$.
\end{conjecture}

\section{Applications and discussion}
The result exemplifies stable arithmetic congruences in wildly growing combinatorial sequences, which are fingerprints of symmetry. The fixed-point parity principle underlies, e.g., Zagier's one-sentence proof that primes $p\equiv 1\pmod4$ are sums of two squares. Practically, $P(n)\equiv 3\pmod 4$ gives an instant sanity check for enumeration software.

The ``unique self-dual object'' phenomenon appears to persist for labeled preorders (self-dual $=$ symmetric $=$ equivalence relations) and labeled $T_0$ topologies (equivalent to partial orders via specialization), suggesting analogous parity theorems. Proving the full modulo-4 congruence via the order-four action is the principal open problem.

\section{Conclusion}
The number $P(n)$ of labeled partial orders on $n$ points is odd for every $n$, as a clean consequence of a single structural fact: the discrete order is the unique self-dual partial order, hence the sole fixed point of duality. The sharper congruence $P(n)\equiv 3\pmod4$---confirmed through a forty-digit value---sits one symmetry level higher, awaiting the analysis of an order-four group combining duality with relabeling.

