"""Demo 1: brute-force enumeration of P(n) and the self-dual count."""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Relation = Tuple[Tuple[bool, ...], ...]

def is_partial_order(rel: Relation, n: int) -> bool:
    for a in range(n):
        if not rel[a][a]:
            return False
    for a in range(n):
        for b in range(n):
            if rel[a][b] and rel[b][a] and a != b:
                return False
    for a in range(n):
        for b in range(n):
            if rel[a][b]:
                for c in range(n):
                    if rel[b][c] and not rel[a][c]:
                        return False
    return True

def all_partial_orders(n: int) -> List[Relation]:
    out: List[Relation] = []
    for bits in product((False, True), repeat=n * n):
        rel = tuple(tuple(bits[a * n + b] for b in range(n)) for a in range(n))
        if is_partial_order(rel, n):
            out.append(rel)
    return out

def dual(rel: Relation, n: int) -> Relation:
    return tuple(tuple(rel[b][a] for b in range(n)) for a in range(n))

for n in range(5):
    orders = all_partial_orders(n)
    self_dual = [r for r in orders if dual(r, n) == r]
    print(f"n={n}: P(n)={len(orders)}, self-dual Q(n)={len(self_dual)}, P odd={len(orders)%2==1}")

"""Demo 3: witness the fixed-point parity principle for the duality involution.

Shows P(n) = |fixed points| + 2 * (#dual pairs), with exactly one fixed point
(the discrete order), hence P(n) is odd.
"""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Relation = Tuple[Tuple[bool, ...], ...]

def is_po(rel: Relation, n: int) -> bool:
    for a in range(n):
        if not rel[a][a]:
            return False
    for a in range(n):
        for b in range(n):
            if rel[a][b] and rel[b][a] and a != b:
                return False
            if rel[a][b]:
                for c in range(n):
                    if rel[b][c] and not rel[a][c]:
                        return False
    return True

def enumerate_po(n: int) -> List[Relation]:
    return [tuple(tuple(bits[a*n+b] for b in range(n)) for a in range(n))
            for bits in product((False, True), repeat=n*n)
            if is_po(tuple(tuple(bits[a*n+b] for b in range(n)) for a in range(n)), n)]

def dual(rel: Relation, n: int) -> Relation:
    return tuple(tuple(rel[b][a] for b in range(n)) for a in range(n))

for n in range(5):
    orders = enumerate_po(n)
    fixed = [r for r in orders if dual(r, n) == r]
    seen: set = set()
    pairs = 0
    for r in orders:
        if r in fixed or r in seen:
            continue
        seen.add(r); seen.add(dual(r, n)); pairs += 1
    print(f"n={n}: P={len(orders)} = fixed({len(fixed)}) + 2*pairs({pairs}) "
          f"= {len(fixed)+2*pairs};  odd={len(orders)%2==1}")

