"""Visualization 3: the duality involution on partial orders for n=3,
drawn as a pairing graph with the single fixed point (discrete order) highlighted."""
from itertools import product
import matplotlib.pyplot as plt
import networkx as nx

def is_po(rel, n):
    for a in range(n):
        if not rel[a][a]:
            return False
    for a in range(n):
        for b in range(n):
            if rel[a][b] and rel[b][a] and a != b:
                return False
            if rel[a][b]:
                for c in range(n):
                    if rel[b][c] and not rel[a][c]:
                        return False
    return True

def dual(rel, n):
    return tuple(tuple(rel[b][a] for b in range(n)) for a in range(n))

n = 3
orders = [tuple(tuple(bits[a*n+b] for b in range(n)) for a in range(n))
          for bits in product((False, True), repeat=n*n)
          if is_po(tuple(tuple(bits[a*n+b] for b in range(n)) for a in range(n)), n)]

G = nx.Graph()
for i, r in enumerate(orders):
    G.add_node(i)
for i, r in enumerate(orders):
    j = orders.index(dual(r, n))
    if i != j:
        G.add_edge(i, j)

fixed = [i for i, r in enumerate(orders) if dual(r, n) == r]
colors = ["gold" if i in fixed else "skyblue" for i in G.nodes]

pos = nx.spring_layout(G, seed=1)
plt.figure(figsize=(9, 7))
nx.draw(G, pos, node_color=colors, with_labels=True, node_size=500, font_size=8)
plt.title(f"Duality pairing on the {len(orders)} partial orders for n=3 "
          f"(gold = unique self-dual / discrete order)")
plt.tight_layout()
plt.savefig("duality_pairing.png", dpi=150)
print("saved duality_pairing.png")
